CREATE TABLE IF NOT EXISTS teachers (teacher_id SERIAL PRIMARY KEY, teacher_code TEXT UNIQUE NOT NULL, full_name TEXT NOT NULL, email TEXT NOT NULL, phone TEXT, subject_specialty TEXT, class_id INTEGER, join_date DATE DEFAULT CURRENT_DATE, status TEXT NOT NULL DEFAULT 'Active');
+CREATE TABLE IF NOT EXISTS classes (class_id SERIAL PRIMARY KEY, class_code TEXT UNIQUE NOT NULL, class_name TEXT NOT NULL, subjects TEXT, schedule_days TEXT, schedule_time TEXT, room TEXT, teacher_id INTEGER REFERENCES teachers(teacher_id) ON DELETE SET NULL, status TEXT NOT NULL DEFAULT 'Active');
+ALTER TABLE teachers ADD CONSTRAINT teachers_class_fk FOREIGN KEY (class_id) REFERENCES classes(class_id) ON DELETE SET NULL;
+CREATE TABLE IF NOT EXISTS students (student_id SERIAL PRIMARY KEY, student_code TEXT UNIQUE NOT NULL, full_name TEXT NOT NULL, gender TEXT, age INTEGER CHECK (age > 0), class_id INTEGER NOT NULL REFERENCES classes(class_id), guardian_name TEXT NOT NULL, guardian_phone TEXT, guardian_email TEXT, enrolment_date DATE DEFAULT CURRENT_DATE, status TEXT NOT NULL DEFAULT 'Active');